```javascript
// Importez Discord.js et enregistrez le client
const { Client, GatewayIntentBits } = require('discord.js');
const client = new Client({
  intents: [GatewayIntentBits.Guilds],
});

// Connexion du client au Discord
client.once('ready', () => {
  console.log('Bot prêt !');
});

// Commande "bannir"
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === 'bannir') {
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Vous n'avez pas la permission de bannir les utilisateurs !',
        ephemeral: true,
      });
    }

    const member = interaction.options.getMember('utilisateur');
    if (!member) {
      return interaction.reply({
        content: 'Veuillez spécifier un utilisateur à bannir !',
        ephemeral: true,
      });
    }

    if (member.permissions.has('ADMINISTRATOR') || member.id === interaction.guild.ownerId) {
      return interaction.reply({
        content: 'Impossible de bannir cet utilisateur !',
        ephemeral: true,
      });
    }

    try {
      await member.ban({ reason: `Bannissement demandé par ${interaction.user.tag}` });
      return interaction.reply({
        content: `${member.user.tag} a été banni avec succès !`,
      });
    } catch (error) {
      console.error(error);
      return interaction.reply({
        content: 'Une erreur est survenue lors du bannissement de cet utilisateur !',
        ephemeral: true,
      });
    }
  }
});

// Connexion du client au Discord
client.login(process.env.TOKEN);
```

