```latex
\documentclass{article}
\usepackage{tikz}
\usepackage{xstring}

\newcommand{\fenToBoard}[1]{
  % Split the FEN string into its components
  \def\board{\StrBefore{#1}{\space}}
  \def\turn{\StrBetween{#1}{\space}{\space}}
  \def\castlings{\StrBetween{#1}{\space}{\space}}
  \def\enPassant{\StrAfter{#1}{\space}}
  \def\halfmoveclock{\StrAfter{\enPassant}{\space}}
  \def/fullmoveclock\temp{\xdef\fullmoveclock{\temp}}

  % Define the board size
  \def\boardSize{8}

  % Convert the FEN board notation to a TikZ matrix
  \def\boardMatrix{%
    \foreach \row in {1,...,\boardSize} {
      \foreach \col in {1,...,\boardSize} {
        \pgfmathtruncatemacro{\cellIndex}{(\row-1)*\boardSize+(\col-1)}
        \edef\piece{\StrChar{\board}{\cellIndex}}
        \if\piece.\relax
          \node [circle, draw=white, minimum size=1cm] at (\col,\row) {};
        \else
          \node [circle, draw, minimum size=1cm] at (\col,\row) {\piece};
        \fi
      }
    }
  }

  % Draw the board
  \begin{tikzpicture}[scale=0.8, every node/.style={transform shape}]
    \draw [step=1cm, gray!20, very thin] (0,0) grid (\boardSize,\boardSize);
    \matrix [matrix of nodes, row sep=\pgflinewidth, column sep=\pgflinewidth, nodes={minimum size=1cm}] at (0.5,-0.5) {\boardMatrix};
  \end{tikzpicture}
}

